"use strict";const{contextBridge:t,ipcRenderer:e}=require("electron");t.exposeInMainWorld("momAPI",{startSession:s=>e.invoke("session:start",s),stopSession:()=>e.invoke("session:stop"),getStatus:()=>e.invoke("session:status"),listSessions:()=>e.invoke("session:list"),getMom:s=>e.invoke("session:get-mom",s),getTranscript:s=>e.invoke("session:get-transcript",s),deleteSession:s=>e.invoke("session:delete",s),getSettings:()=>e.invoke("settings:get"),saveSettings:s=>e.invoke("settings:save",s),minimize:()=>e.send("app:minimize"),maximize:()=>e.send("app:maximize"),close:()=>e.send("app:close"),onProgress:s=>{const i=(o,n)=>s(n);return e.on("progress",i),()=>e.removeListener("progress",i)}});
